const SKILLS_DB={"meta": {"总数": 120, "环节": ["文献调研", "假设生成", "实验与计算", "数据分析", "论文写作", "诚信治理"], "学科": ["生命科学", "物质科学", "地球环境", "数学量子", "工程技术", "交叉通用"], "类型": ["即装即用", "需GPU/远程", "数据连接器"], "来源": ["claude-scientific-skills", "OpenAI4S", "open-science"]}, "skills": [{"id": "networkx", "name": "networkx", "description": "Create, analyze, and visualize complex networks and graphs in Python with NetworkX. Use when working with network/graph data structures, computing graph algorithms (shortest paths, centrality, clustering), detecting communities, generating synthetic networks (random, scale-free, small-world), reading/writing graph file formats, or drawing network topologies. Common applications include social, biological, transportation, and citation networks.", "source": "claude-scientific-skills", "path": "skills/networkx/SKILL.md", "dir": "skills/networkx", "环节": "文献调研", "学科": "生命科学", "类型": "即装即用", "cn": "用NetworkX在Python中创建、分析和可视化复杂网络与图"}, {"id": "paper-lookup", "name": "paper-lookup", "description": "Search 10 academic literature APIs for papers, preprints, citations, and open-access full text, and return results with reproducible provenance. Covers PubMed, PMC (full text), bioRxiv, medRxiv, arXiv, OpenAlex, Crossref, Semantic Scholar, CORE, Unpaywall. Use when searching for papers, citations, DOI/PMID/arXiv lookups, abstracts, full text, open-access PDFs, preprints, citation graphs, author publications, or any scholarly literature query. Triggers on mentions of any supported database or req", "source": "claude-scientific-skills", "path": "skills/paper-lookup/SKILL.md", "dir": "skills/paper-lookup", "环节": "文献调研", "学科": "生命科学", "类型": "即装即用", "cn": "跨10个学术API检索文献并返回可复现的出处信息"}, {"id": "evidence-walkthrough", "name": "evidence-walkthrough", "description": "Run the reference end-to-end research pass — fixed database query, local analysis, versioned artifacts with lineage, then an exported evidence package that verifies in a clean environment. Use as the first-run demonstration, as a benchmark case, or when a result must be handed to someone who was not there when it ran.", "source": "OpenAI4S", "path": "skills/evidence-walkthrough/SKILL.md", "dir": "skills/evidence-walkthrough", "环节": "文献调研", "学科": "交叉通用", "类型": "即装即用", "cn": "运行端到端研究流程，导出可在干净环境验证的证据包"}, {"id": "exa-search", "name": "exa-search", "description": "Web toolkit powered by Exa, tuned for scientific and technical content. Use this skill when the user needs to search the web or fetch/extract URL content. Covers: web search (semantic lookups, research, current info — with optional research-paper category and academic domain filtering) and URL extraction (fetching pages, articles, academic PDFs in batch). Use this skill for web-related tasks when the user wants high-quality search or scholarly filtering via category=research paper. Triggers on r", "source": "claude-scientific-skills", "path": "skills/exa-search/SKILL.md", "dir": "skills/exa-search", "环节": "文献调研", "学科": "交叉通用", "类型": "即装即用", "cn": "用Exa搜索网页或抓取URL内容，专注科技类信息"}, {"id": "literature-review", "name": "literature-review", "description": "Conduct comprehensive, systematic literature reviews using multiple academic databases (PubMed, arXiv, bioRxiv, Semantic Scholar, etc.). This skill should be used when conducting systematic literature reviews, meta-analyses, research synthesis, or comprehensive literature searches across biomedical, scientific, and technical domains. Creates professionally formatted markdown documents and PDFs with verified citations in multiple citation styles (APA, Nature, Vancouver, etc.).", "source": "claude-scientific-skills+OpenAI4S", "path": "skills/literature-review/SKILL.md", "dir": "skills/literature-review", "环节": "文献调研", "学科": "交叉通用", "类型": "即装即用", "cn": "用PubMed、arXiv等多数据库开展系统性文献综述"}, {"id": "paper-narrative", "name": "paper-narrative", "description": "Judge and reshape the STORY a paper's figures tell. Input is the work itself — manuscript (or abstract) + figure deck — no hand-written brief. `derive_paper_brief(abstract, captions)` extracts pitch/vision/per-figure-claims; a handling-editor reviewer on the full deck returns hook_verdict (would Fig 1 make me send this for review?), arc (hook→mechanism→evidence→application), figure_moves (panels in the wrong figure), missing_panels (concrete analyses to RUN), kill_list, and boldest_defensible_fi", "source": "OpenAI4S", "path": "skills/paper-narrative/SKILL.md", "dir": "skills/paper-narrative", "环节": "文献调研", "学科": "交叉通用", "类型": "即装即用", "cn": "评估并重塑论文图表所讲述的故事主线"}, {"id": "pdf-explore", "name": "pdf-explore", "description": "Use this skill when the user has attached a PDF, paper, report, or other document and the answer needs content from more than one place in it: summarize the methods or any other section, compare sections, find where a topic is discussed, read a value or label off a figure or chart, or find/list/extract every instance of something across the whole document (datasets, benchmarks, citations, figures, table rows, accession numbers — including appendices). Skip it only for a single lookup of 1–4 page", "source": "OpenAI4S", "path": "skills/pdf-explore/SKILL.md", "dir": "skills/pdf-explore", "环节": "文献调研", "学科": "交叉通用", "类型": "即装即用", "cn": "从PDF多处提取内容：总结章节、比较不同部分"}, {"id": "pyzotero", "name": "pyzotero", "description": "Interact with Zotero reference management libraries using the pyzotero Python client. Retrieve, create, update, and delete items, collections, tags, and attachments via the Zotero Web API v3. Use this skill when working with Zotero libraries programmatically, managing bibliographic references, exporting citations, searching library contents, uploading PDF attachments, or building research automation workflows that integrate with Zotero.", "source": "claude-scientific-skills", "path": "skills/pyzotero/SKILL.md", "dir": "skills/pyzotero", "环节": "文献调研", "学科": "交叉通用", "类型": "即装即用", "cn": "用pyzotero通过Zotero API管理文献条目与附件"}, {"id": "research-grants", "name": "research-grants", "description": "Write competitive research proposals for NSF, NIH, DOE, DARPA, and Taiwan NSTC. Agency-specific formatting, review criteria, budget preparation, broader impacts, significance statements, innovation narratives, and compliance with submission requirements.", "source": "claude-scientific-skills", "path": "skills/research-grants/SKILL.md", "dir": "skills/research-grants", "环节": "文献调研", "学科": "交叉通用", "类型": "即装即用", "cn": "撰写NSF、NIH等机构的有竞争力研究申请书"}, {"id": "research-lookup", "name": "research-lookup", "description": "Compile current scholarly evidence for a scientific manuscript or research brief. Use when the user explicitly asks to gather literature, references, background evidence, competing findings, or a manuscript research packet. Uses Parallel Search by default, Parallel Extract for source verification, Parallel Research for explicitly deep/exhaustive work, optional explicit Parallel Chat, and optional Perplexity only when requested or allowed as a failure fallback.", "source": "claude-scientific-skills", "path": "skills/research-lookup/SKILL.md", "dir": "skills/research-lookup", "环节": "文献调研", "学科": "交叉通用", "类型": "即装即用", "cn": "为科研手稿汇编最新学术证据与参考文献"}, {"id": "hypothesis-generation", "name": "hypothesis-generation", "description": "Formulate evidence-bounded scientific questions, candidate hypotheses, rival explanations, causal or associational claims, discriminating predictions, measurements, and preregistration-ready analysis plans. Use when turning observations or preliminary findings into transparent, testable research plans without treating hypotheses as facts.", "source": "claude-scientific-skills", "path": "skills/hypothesis-generation/SKILL.md", "dir": "skills/hypothesis-generation", "环节": "假设生成", "学科": "生命科学", "类型": "即装即用", "cn": "生成有证据边界的科学假设、预测与预注册分析方案"}, {"id": "scientific-brainstorming", "name": "scientific-brainstorming", "description": "Facilitates evidence-aware scientific ideation with independent generation, structured discussion, explicit assumptions, transparent evaluation, adversarial review, and decision logs. Use for early-stage research brainstorming or prioritizing candidate directions; hand off empirical validation, study design, ethics or regulatory review, and clinical questions to appropriate experts or skills.", "source": "claude-scientific-skills", "path": "skills/scientific-brainstorming/SKILL.md", "dir": "skills/scientific-brainstorming", "环节": "假设生成", "学科": "生命科学", "类型": "即装即用", "cn": "推动证据驱动的科研头脑风暴，含对抗评审与决策记录"}, {"id": "experimental-design", "name": "experimental-design", "description": "Design experiments and studies BEFORE data is collected — choosing a design, randomizing, blocking, and laying out treatment combinations so the results will actually be interpretable. Use whenever someone is planning a study, asks how to assign subjects/samples to groups, mentions randomization, blocking, stratification, controls, factorial or fractional-factorial designs, design of experiments (DOE), screening many factors, response-surface optimization, crossover or repeated-measures or split", "source": "claude-scientific-skills", "path": "skills/experimental-design/SKILL.md", "dir": "skills/experimental-design", "环节": "假设生成", "学科": "数学量子", "类型": "即装即用", "cn": "在收集数据前设计实验，确保结果可解释"}, {"id": "plan-ml-experiment", "name": "plan-ml-experiment", "description": "Plan reproducible machine-learning experiments with leakage-safe random, grouped, or chronological splits; deterministic configuration fingerprints; dataset checksums; seeds, baselines, ablations, and artifact manifests.", "source": "OpenAI4S", "path": "skills/plan-ml-experiment/SKILL.md", "dir": "skills/plan-ml-experiment", "环节": "假设生成", "学科": "交叉通用", "类型": "即装即用", "cn": "规划可复现的机器学习实验，防止数据泄漏"}, {"id": "scientific-critical-thinking", "name": "scientific-critical-thinking", "description": "Evaluate scientific claims and evidence quality. Use for assessing experimental design validity, identifying biases and confounders, applying evidence grading frameworks (GRADE, Cochrane Risk of Bias), or teaching critical analysis. Best for understanding evidence quality, identifying flaws. For formal peer review writing use peer-review.", "source": "claude-scientific-skills", "path": "skills/scientific-critical-thinking/SKILL.md", "dir": "skills/scientific-critical-thinking", "环节": "假设生成", "学科": "交叉通用", "类型": "即装即用", "cn": "评估科学主张与证据质量，识别偏倚"}, {"id": "statistical-analysis", "name": "statistical-analysis", "description": "Guided statistical analysis for research data - test selection, assumption checking, effect sizes, power analysis, Bayesian alternatives, and APA-formatted reporting. Use whenever a user wants to compare groups, test a hypothesis, analyze experimental or survey data, check statistical assumptions, compute required sample sizes, or write up results - even if they never name a specific test. Covers t-tests, ANOVA, chi-square, correlation, regression, non-parametric and Bayesian methods. For low-le", "source": "claude-scientific-skills", "path": "skills/statistical-analysis/SKILL.md", "dir": "skills/statistical-analysis", "环节": "假设生成", "学科": "交叉通用", "类型": "即装即用", "cn": "指导统计检验选择与假设检验，输出APA格式报告"}, {"id": "admet_genetic", "name": "admet_genetic", "description": "ADMET-guided genetic molecule optimization workflow from seed SMILES; use when the agent needs to build or run an RDKit/SA-Score/ADMET-AI GA pipeline for molecule optimization, enforce molecule lineage logs, render optimization-history HTML dashboards, and write candidate triage reports.", "source": "OpenAI4S", "path": "skills/admet_genetic/SKILL.md", "dir": "skills/admet_genetic", "环节": "实验与计算", "学科": "生命科学", "类型": "即装即用", "cn": "基于ADMET的遗传算法分子优化流程"}, {"id": "alphafold2", "name": "alphafold2", "description": "Predict protein structure for monomers and multimers with AlphaFold2 via the ColabFold runner (Mirdita et al. 2022, github.com/sokrypton/ColabFold; AlphaFold2 Jumper et al. 2021). Reach for this skill to fold a sequence or complex with the AF2/AF2-Multimer evoformer, to validate designed sequences by self-consistency pLDDT, ipTM, and RMSD, or to run a quick MSA-backed prediction using the public MMseqs2 server.", "source": "OpenAI4S", "path": "skills/alphafold2/SKILL.md", "dir": "skills/alphafold2", "环节": "实验与计算", "学科": "生命科学", "类型": "需GPU/远程", "cn": "用AlphaFold2预测蛋白质单体及复合物结构"}, {"id": "anndata", "name": "anndata", "description": "Data structure for annotated matrices in single-cell analysis. Use when working with .h5ad files or integrating with the scverse ecosystem. This is the data format skill—for analysis workflows use scanpy; for probabilistic models use scvi-tools; for population-scale queries use cellxgene-census.", "source": "claude-scientific-skills", "path": "skills/anndata/SKILL.md", "dir": "skills/anndata", "环节": "实验与计算", "学科": "生命科学", "类型": "即装即用", "cn": "单细胞分析中AnnData标注矩阵数据结构处理"}, {"id": "arboreto", "name": "arboreto", "description": "Infer gene regulatory networks (GRNs) from gene expression data using scalable algorithms (GRNBoost2, GENIE3). Use when analyzing transcriptomics data (bulk RNA-seq, single-cell RNA-seq) to identify transcription factor-target gene relationships and regulatory interactions. Supports distributed computation for large-scale datasets.", "source": "claude-scientific-skills", "path": "skills/arboreto/SKILL.md", "dir": "skills/arboreto", "环节": "实验与计算", "学科": "生命科学", "类型": "即装即用", "cn": "用GRNBoost2/GENIE3从表达数据推断基因调控网络"}, {"id": "bids", "name": "bids", "description": "Use this skill when working with Brain Imaging Data Structure (BIDS) datasets: organizing neuroscience and biomedical data (MRI, EEG, MEG, iEEG, PET, microscopy, NIRS, motion capture, EMG, MR spectroscopy, behavioral), querying BIDS layouts, validating compliance, converting DICOM to BIDS, writing metadata sidecars, or creating BIDS derivatives.", "source": "claude-scientific-skills", "path": "skills/bids/SKILL.md", "dir": "skills/bids", "环节": "实验与计算", "学科": "生命科学", "类型": "即装即用", "cn": "组织管理BIDS标准的脑影像与神经科学数据"}, {"id": "biopython", "name": "biopython", "description": "Comprehensive molecular biology toolkit. Use for sequence manipulation, file parsing (FASTA/GenBank/PDB), phylogenetics, and programmatic NCBI/PubMed access (Bio.Entrez). Best for batch processing, custom bioinformatics pipelines, BLAST automation. For quick lookups use gget; for multi-service integration use bioservices.", "source": "claude-scientific-skills", "path": "skills/biopython/SKILL.md", "dir": "skills/biopython", "环节": "实验与计算", "学科": "生命科学", "类型": "即装即用", "cn": "用Biopython进行序列操作、文件解析与NCBI访问"}, {"id": "bioservices", "name": "bioservices", "description": "Unified Python interface to 40+ bioinformatics services. Use when querying multiple databases (UniProt, KEGG, ChEMBL, Reactome) in a single workflow with consistent API. Best for cross-database analysis, ID mapping across services. For quick single-database lookups use gget; for sequence/file manipulation use biopython.", "source": "claude-scientific-skills", "path": "skills/bioservices/SKILL.md", "dir": "skills/bioservices", "环节": "实验与计算", "学科": "生命科学", "类型": "数据连接器", "cn": "统一接口查询UniProt等40余个生物信息数据库"}, {"id": "boltz", "name": "boltz", "description": "Structure prediction for protein, nucleic-acid, and small-molecule complexes with Boltz-2 (Passaro & Wohlwend et al. 2025, github.com/jwohlwend/boltz). Reach for this skill to validate designed binders against a target, to co-fold a protein with a SMILES or CCD ligand, or to get an open-source AlphaFold3 alternative with optional binding-affinity prediction.", "source": "OpenAI4S", "path": "skills/boltz/SKILL.md", "dir": "skills/boltz", "环节": "实验与计算", "学科": "生命科学", "类型": "需GPU/远程", "cn": "用Boltz-2预测蛋白质-核酸-小分子复合物结构"}, {"id": "borzoi", "name": "borzoi", "description": "Predict genome-wide functional tracks (RNA-seq, CAGE, DNase, ChIP) from DNA sequence with Borzoi. Use this skill when: (1) Scoring the regulatory effect of a variant on expression/accessibility, (2) Generating predicted coverage tracks for a locus, (3) Prioritising non-coding variants by predicted track delta.", "source": "OpenAI4S", "path": "skills/borzoi/SKILL.md", "dir": "skills/borzoi", "环节": "实验与计算", "学科": "生命科学", "类型": "需GPU/远程", "cn": "用Borzoi从DNA序列预测全基因组功能信号并评估变异调控效应"}, {"id": "bulk-rnaseq", "name": "bulk-rnaseq", "description": "End-to-end bulk RNA-seq orchestrator — takes raw FASTQ reads through QC and trimming (FastQC, fastp/Trim Galore), alignment and quantification (STAR, Salmon, featureCounts), assembles a gene-level counts matrix, then hands off to differential expression (pydeseq2), pathway/GSEA enrichment (pathway-enrichment), and publication figures (scientific-visualization). Use whenever the user has bulk RNA-seq reads or quant output and wants a complete, reproducible differential-expression workflow — e.g. ", "source": "claude-scientific-skills", "path": "skills/bulk-rnaseq/SKILL.md", "dir": "skills/bulk-rnaseq", "环节": "实验与计算", "学科": "生命科学", "类型": "即装即用", "cn": "一站式完成bulk RNA-seq从原始reads到基因定量分析"}, {"id": "cellxgene-census", "name": "cellxgene-census", "description": "Query the CZ CELLxGENE Census programmatically for versioned public single-cell and spatial transcriptomics data. Use when you need population-scale cell metadata, gene expression slices, Census summary counts, source H5AD URIs/downloads, embeddings, spatial Census data, or reference atlas comparisons across organisms, tissues, diseases, assays, and cell types. For analyzing your own local single-cell data use scanpy, anndata, or scvi-tools.", "source": "claude-scientific-skills", "path": "skills/cellxgene-census/SKILL.md", "dir": "skills/cellxgene-census", "环节": "实验与计算", "学科": "生命科学", "类型": "数据连接器", "cn": "编程查询CELLxGENE Census大规模单细胞与空间转录组数据"}, {"id": "chai1", "name": "chai1", "description": "Structure prediction for protein, nucleic-acid, and small-molecule complexes with the Chai-1 foundation model (Chai Discovery 2024, github.com/chaidiscovery/chai-lab). Reach for this skill to predict an antibody-antigen or protein-ligand complex from a single FASTA, to re-fold designed binders as an AlphaFold-multimer alternative, or to drive co-folding from Python for batched campaigns on a GPU.", "source": "OpenAI4S", "path": "skills/chai1/SKILL.md", "dir": "skills/chai1", "环节": "实验与计算", "学科": "生命科学", "类型": "需GPU/远程", "cn": "用Chai-1预测蛋白质、核酸及小分子复合物三维结构"}, {"id": "cobrapy", "name": "cobrapy", "description": "Constraint-based metabolic modeling (COBRA). FBA, FVA, gene knockouts, flux sampling, SBML models, for systems biology and metabolic engineering analysis.", "source": "claude-scientific-skills", "path": "skills/cobrapy/SKILL.md", "dir": "skills/cobrapy", "环节": "实验与计算", "学科": "生命科学", "类型": "即装即用", "cn": "用COBRApy做代谢约束建模与通量分析"}, {"id": "deeptools", "name": "deeptools", "description": "NGS analysis toolkit. BAM to bigWig conversion, QC (correlation, PCA, fingerprints), heatmaps/profiles (TSS, peaks), for ChIP-seq, RNA-seq, ATAC-seq visualization.", "source": "claude-scientific-skills", "path": "skills/deeptools/SKILL.md", "dir": "skills/deeptools", "环节": "实验与计算", "学科": "生命科学", "类型": "即装即用", "cn": "用deepTools处理NGS数据并可视化ChIP-seq等结果"}, {"id": "depmap", "name": "depmap", "description": "Query the Cancer Dependency Map (DepMap) for cancer cell line gene dependency scores (CRISPR Chronos), drug sensitivity data, and gene effect profiles. Use for identifying cancer-specific vulnerabilities, synthetic lethal interactions, and validating oncology drug targets.", "source": "claude-scientific-skills", "path": "skills/depmap/SKILL.md", "dir": "skills/depmap", "环节": "实验与计算", "学科": "生命科学", "类型": "数据连接器", "cn": "查询DepMap获取癌细胞基因依赖性与药敏数据"}, {"id": "diffdock", "name": "diffdock", "description": "Predict small-molecule binding poses with DiffDock-L (Corso et al. 2023/2024, github.com/gcorso/DiffDock) — blind diffusion docking that places a ligand into a protein pocket without a predefined search box and ranks the samples with a learned confidence model. Reach for this skill to dock a SMILES or SDF against a PDB, to generate ranked 3D poses for a small fragment library, or to get a starting pose for downstream rescoring. DiffDock predicts geometry, not affinity.", "source": "claude-scientific-skills+OpenAI4S", "path": "skills/diffdock/SKILL.md", "dir": "skills/diffdock", "环节": "实验与计算", "学科": "生命科学", "类型": "即装即用", "cn": "用DiffDock-L预测小分子与蛋白口袋的结合构象"}, {"id": "esm", "name": "esm", "description": "Use when working directly with the `esm` Python SDK, ESM3 or ESMC model IDs, Forge/Biohub inference clients, or ESMFold2 folding workflows.", "source": "claude-scientific-skills", "path": "skills/esm/SKILL.md", "dir": "skills/esm", "环节": "实验与计算", "学科": "生命科学", "类型": "即装即用", "cn": "通过esm SDK调用ESM3/ESMC模型进行蛋白分析"}, {"id": "esmfold2", "name": "esmfold2", "description": "Biohub ESMFold2 / ESMFold2-Fast all-atom co-folding (Candido et al. 2026, github.com/Biohub/esm). Single-sequence and MSA modes; protein, DNA, RNA, ligand (CCD/SMILES), modified residues. FoldBench Ab-Ag 50-55%, PPI 70-77% DockQ-pass. Also covers the ESMC-{300M,600M,6B} protein language models from the same release: masked-LM logits, hidden states, mutation scoring, contact prediction, and the SAE interpretability head. MIT-licensed weights on HuggingFace org `biohub`. Use this skill when: (1) P", "source": "OpenAI4S", "path": "skills/esmfold2/SKILL.md", "dir": "skills/esmfold2", "环节": "实验与计算", "学科": "生命科学", "类型": "需GPU/远程", "cn": "用ESMFold2进行蛋白质核酸配体的全原子共折叠"}, {"id": "evo2", "name": "evo2", "description": "Score, embed, and generate DNA sequences with Evo 2, a long-context genomic foundation model. Use this skill when: (1) Computing per-nucleotide or per-sequence likelihoods for variant effect scoring, (2) Embedding genomic windows for downstream classification, (3) Generating DNA conditioned on a prefix, (4) Scoring regulatory or coding regions across species.", "source": "OpenAI4S", "path": "skills/evo2/SKILL.md", "dir": "skills/evo2", "环节": "实验与计算", "学科": "生命科学", "类型": "需GPU/远程", "cn": "用Evo 2对DNA序列打分、嵌入并评估变异效应"}, {"id": "fair-esm2", "name": "fair-esm2", "description": "Embed proteins with Meta AI's ESM-2 (`fair-esm` package). Use this skill when: (1) Extracting per-residue or per-sequence embeddings for downstream ML, (2) Masked-LM likelihood / mutation effect scoring, (3) Contact prediction from a sequence.", "source": "OpenAI4S", "path": "skills/fair-esm2/SKILL.md", "dir": "skills/fair-esm2", "环节": "实验与计算", "学科": "生命科学", "类型": "需GPU/远程", "cn": "用ESM-2提取蛋白质序列嵌入并评估突变效应"}, {"id": "flowio", "name": "flowio", "description": "Read, inspect, and write Flow Cytometry Standard (FCS) 2.0, 3.0, and 3.1 files with FlowIO. Use for low-level FCS metadata and channel inspection, NumPy event extraction, multi-dataset files, table export, and FCS 3.1 creation; use FlowKit for compensation, cytometry transforms, gating, or FlowJo workspaces.", "source": "claude-scientific-skills", "path": "skills/flowio/SKILL.md", "dir": "skills/flowio", "环节": "实验与计算", "学科": "生命科学", "类型": "即装即用", "cn": "用FlowIO读写FCS文件，提取流式细胞术元数据和事件数据。"}, {"id": "genomic-intelligence", "name": "genomic-intelligence", "description": "Predict regulatory features, gene structure, and expression directly from DNA sequence using Genomic Intelligence's hosted transformer DNA language models — no local GPU or model weights. Six tasks over a REST API and a hosted MCP server (keyless public demo): promoter regions, splice donor/acceptor sites, enhancer activity, chromatin state, sequence-to-expression (log TPM), and de-novo gene annotation, plus a composite find-genes-then-predict-expression workflow. Use when the user has a gene sy", "source": "claude-scientific-skills", "path": "skills/genomic-intelligence/SKILL.md", "dir": "skills/genomic-intelligence", "环节": "实验与计算", "学科": "生命科学", "类型": "数据连接器", "cn": "通过Genomic Intelligence的DNA语言模型预测调控特征、基因结构和表达。"}, {"id": "gget", "name": "gget", "description": "Fast CLI/Python queries to 20+ bioinformatics databases. Use for quick lookups: gene info, BLAST/BLAT, viral sequence downloads, AlphaFold structures, enrichment analysis, OpenTargets, COSMIC, CELLxGENE, and 8cube mouse specificity/expression data. Best for interactive exploration and simple queries. For batch processing or advanced BLAST use biopython; for multi-database Python workflows use bioservices.", "source": "claude-scientific-skills", "path": "skills/gget/SKILL.md", "dir": "skills/gget", "环节": "实验与计算", "学科": "生命科学", "类型": "数据连接器", "cn": "用gget快速查询20多个生物信息数据库，获取基因、序列和结构信息。"}, {"id": "glycoengineering", "name": "glycoengineering", "description": "Analyze and engineer protein glycosylation. Scan sequences for N-glycosylation sequons (N-X-S/T), predict O-glycosylation hotspots, and access curated glycoengineering tools (NetOGlyc, GlycoShield, GlycoWorkbench). For glycoprotein engineering, therapeutic antibody optimization, and vaccine design.", "source": "claude-scientific-skills", "path": "skills/glycoengineering/SKILL.md", "dir": "skills/glycoengineering", "环节": "实验与计算", "学科": "生命科学", "类型": "即装即用", "cn": "分析蛋白质糖基化，扫描N-糖基化位点并预测O-糖基化热点。"}, {"id": "hugging-science", "name": "hugging-science", "description": "Use when the user is doing AI/ML work in a scientific domain such as biology, chemistry, physics, astronomy, climate, genomics, materials, medicine, ecology, energy, engineering, math, drug discovery, protein design, weather modeling, theorem proving, single-cell, or PDE solving. Hugging Science is a curated catalog of scientific datasets, models, blog posts, and interactive Spaces. This skill helps discover and use resources via `datasets`, `transformers`, the HF Inference API, `gradio_client`,", "source": "claude-scientific-skills", "path": "skills/hugging-science/SKILL.md", "dir": "skills/hugging-science", "环节": "实验与计算", "学科": "生命科学", "类型": "数据连接器", "cn": "为生物、化学、物理等科学领域的AI/ML工作提供支持。"}, {"id": "imaging-data-commons", "name": "imaging-data-commons", "description": "Query and download public cancer imaging data from NCI Imaging Data Commons using idc-index. Use for accessing large-scale radiology (CT, MR, PET) and pathology datasets for AI training or research. No authentication required. Query by metadata, visualize in browser, check licenses.", "source": "claude-scientific-skills", "path": "skills/imaging-data-commons/SKILL.md", "dir": "skills/imaging-data-commons", "环节": "实验与计算", "学科": "生命科学", "类型": "数据连接器", "cn": "用idc-index查询下载NCI癌症影像数据，用于AI训练或研究。"}, {"id": "indication-dossier", "name": "indication-dossier", "description": "Generate a therapeutic indication dossier. Covers the patient population, epidemiology, disease biology, standard of care, regulatory precedent, and landmark clinical trials.", "source": "OpenAI4S", "path": "skills/indication-dossier/SKILL.md", "dir": "skills/indication-dossier", "环节": "实验与计算", "学科": "生命科学", "类型": "即装即用", "cn": "生成治疗适应症档案，涵盖患者群体、流行病学和临床试验。"}, {"id": "ligandmpnn", "name": "ligandmpnn", "description": "Inverse-fold a backbone with ligand, nucleic-acid, and metal context using LigandMPNN (Dauparas et al. 2023, github.com/dauparas/LigandMPNN). Reach for this skill to redesign the residues lining a binding pocket around a bound small molecule or cofactor, to design metal-coordinating sites where the geometry must be respected, or to get threaded designed-sequence PDBs out of any MPNN run.", "source": "OpenAI4S", "path": "skills/ligandmpnn/SKILL.md", "dir": "skills/ligandmpnn", "环节": "实验与计算", "学科": "生命科学", "类型": "需GPU/远程", "cn": "用LigandMPNN在配体、核酸和金属环境下逆折叠蛋白质骨架。"}, {"id": "medchem", "name": "medchem", "description": "Medicinal chemistry filters for compound triage. Apply drug-likeness rules (Lipinski, Veber, CNS), structural alert catalogs (PAINS, NIBR, ChEMBL), complexity metrics, and the medchem query language for library filtering.", "source": "claude-scientific-skills", "path": "skills/medchem/SKILL.md", "dir": "skills/medchem", "环节": "实验与计算", "学科": "生命科学", "类型": "即装即用", "cn": "用medchem应用药物相似性规则和结构警报筛选化合物。"}, {"id": "molecular-dynamics", "name": "molecular-dynamics", "description": "Run and analyze molecular dynamics simulations with OpenMM and MDAnalysis. Set up protein/small molecule systems, define force fields, run energy minimization and production MD, analyze trajectories (RMSD, RMSF, contact maps, free energy surfaces). For structural biology, drug binding, and biophysics.", "source": "claude-scientific-skills", "path": "skills/molecular-dynamics/SKILL.md", "dir": "skills/molecular-dynamics", "环节": "实验与计算", "学科": "生命科学", "类型": "即装即用", "cn": "用OpenMM和MDAnalysis运行分析分子动力学模拟。"}, {"id": "neuropixels-analysis", "name": "neuropixels-analysis", "description": "Analyze Neuropixels extracellular recordings end-to-end with SpikeInterface. Covers loading SpikeGLX/Open Ephys/NWB data, preprocessing, drift/motion correction, Kilosort4 (and CPU) spike sorting, quality metrics, and unit curation (threshold-based, model-based UnitRefine, and AI-assisted visual review). Use when working with Neuropixels 1.0/2.0 recordings, spike sorting, or extracellular electrophysiology analysis.", "source": "claude-scientific-skills", "path": "skills/neuropixels-analysis/SKILL.md", "dir": "skills/neuropixels-analysis", "环节": "实验与计算", "学科": "生命科学", "类型": "即装即用", "cn": "用SpikeInterface端到端分析Neuropixels细胞外记录数据。"}, {"id": "nextflow", "name": "nextflow", "description": "Build, run, and debug Nextflow data pipelines and nf-core workflows end to end. Use whenever the user mentions Nextflow, nf-core, .nf files, nextflow.config, DSL2, processes/channels/operators, samplesheets, or wants to run a community pipeline (e.g. nf-core/rnaseq, nf-core/sarek), write or test a module/subworkflow with nf-test, configure executors/containers (Docker, Singularity/Apptainer, Conda, Wave), scale a workflow to HPC/SLURM or cloud (AWS Batch, Google Batch, Azure, Kubernetes), or deb", "source": "claude-scientific-skills", "path": "skills/nextflow/SKILL.md", "dir": "skills/nextflow", "环节": "实验与计算", "学科": "生命科学", "类型": "即装即用", "cn": "构建、运行和调试Nextflow数据管道及nf-core工作流。"}, {"id": "onekgpd", "name": "onekgpd", "description": "Query the 1000 Genomes Project dataset (3,202 whole-genome-sequenced individuals, GRCh38) at the level of individual participants. Use when a question is about individuals or variants in the 1000 Genomes Project cohort: which individuals carry variants matching specific criteria in a gene or region, which individuals are homozygous-reference at a position, which variants exist in the dataset or carried by specified individuals in a gene or region, the relatedness between two specified individual", "source": "claude-scientific-skills", "path": "skills/onekgpd/SKILL.md", "dir": "skills/onekgpd", "环节": "实验与计算", "学科": "生命科学", "类型": "数据连接器", "cn": "查询1000 Genomes Project中3202个个体的基因组数据"}, {"id": "openfold3", "name": "openfold3", "description": "Structure prediction using OpenFold3, an open-weights PyTorch reproduction of AlphaFold3 from the AlQuraishi Lab. Use this skill when predicting protein/nucleic-acid/ligand complex structures with an Apache-2.0-licensed AF3 reimplementation.", "source": "OpenAI4S", "path": "skills/openfold3/SKILL.md", "dir": "skills/openfold3", "环节": "实验与计算", "学科": "生命科学", "类型": "需GPU/远程", "cn": "用OpenFold3预测蛋白质/核酸/配体复合物结构"}, {"id": "opentrons-integration", "name": "opentrons-integration", "description": "Author, review, migrate, simulate, and troubleshoot official Opentrons Python Protocol API v2 protocols for Flex and OT-2 robots. Use for robot-specific liquid handling, deck and labware setup, pipettes, modules, runtime parameters, liquid classes, and Opentrons App analysis. Use pylabrobot instead when one workflow must support multiple robot vendors.", "source": "claude-scientific-skills", "path": "skills/opentrons-integration/SKILL.md", "dir": "skills/opentrons-integration", "环节": "实验与计算", "学科": "生命科学", "类型": "即装即用", "cn": "编写和调试Opentrons机器人液体处理协议"}, {"id": "pathml", "name": "pathml", "description": "Use PathML for local, research-only computational pathology workflows: load and tile slides, build preprocessing and QC pipelines, manage h5path data, quantify multiplex images, construct spatial graphs, and plan bounded model inference.", "source": "claude-scientific-skills", "path": "skills/pathml/SKILL.md", "dir": "skills/pathml", "环节": "实验与计算", "学科": "生命科学", "类型": "即装即用", "cn": "用PathML进行病理切片分析和空间图谱构建"}, {"id": "pathway-enrichment", "name": "pathway-enrichment", "description": "Run pathway and gene-set enrichment analysis on gene lists or ranked gene data, then interpret the results. Use whenever the user has a set of genes (differentially expressed genes from PyDESeq2/Scanpy, CRISPR-screen hits, cluster marker genes, proteomics hits) and wants to know which biological pathways, GO terms, or gene sets are over-represented or enriched. Covers over-representation analysis (ORA / Enrichr / Fisher / hypergeometric), ranked Gene Set Enrichment Analysis (GSEA / preranked), s", "source": "claude-scientific-skills", "path": "skills/pathway-enrichment/SKILL.md", "dir": "skills/pathway-enrichment", "环节": "实验与计算", "学科": "生命科学", "类型": "即装即用", "cn": "对基因列表进行通路富集分析并解读结果"}, {"id": "phylogenetics", "name": "phylogenetics", "description": "Build and analyze phylogenetic trees using MAFFT (multiple alignment), IQ-TREE 2 (maximum likelihood), and FastTree (fast NJ/ML). Visualize with ETE3 or FigTree. For evolutionary analysis, microbial genomics, viral phylodynamics, protein family analysis, and molecular clock studies.", "source": "claude-scientific-skills", "path": "skills/phylogenetics/SKILL.md", "dir": "skills/phylogenetics", "环节": "实验与计算", "学科": "生命科学", "类型": "即装即用", "cn": "用MAFFT/IQ-TREE等工具构建系统发育树"}, {"id": "primekg", "name": "primekg", "description": "Query the Precision Medicine Knowledge Graph (PrimeKG) for multiscale biological data including genes, drugs, diseases, phenotypes, and more.", "source": "claude-scientific-skills", "path": "skills/primekg/SKILL.md", "dir": "skills/primekg", "环节": "实验与计算", "学科": "生命科学", "类型": "数据连接器", "cn": "查询PrimeKG精准医学知识图谱的多尺度数据"}, {"id": "protein-mutation-enhancement", "name": "protein-mutation-enhancement", "description": "Deterministic protein gain-of-function mutation workflow: build single, double, and higher-order mutant libraries; merge ESM sequence-effect scores, structure metrics from ESMFold-class models, property/function scores; rank candidates; and decide whether to stop or start the next design round.", "source": "OpenAI4S", "path": "skills/protein-mutation-enhancement/SKILL.md", "dir": "skills/protein-mutation-enhancement", "环节": "实验与计算", "学科": "生命科学", "类型": "即装即用", "cn": "构建蛋白质功能增强突变体库并评分筛选"}, {"id": "proteinmpnn", "name": "proteinmpnn", "description": "Inverse-fold a protein backbone (PDB structure) into amino-acid sequence with ProteinMPNN (Dauparas et al. 2022, github.com/dauparas/ProteinMPNN). Reach for this skill to run sequence design on RFdiffusion backbones, to redesign one chain of a PDB while holding interface residues fixed, or to generate a temperature-swept set of sequences for downstream folding.", "source": "OpenAI4S", "path": "skills/proteinmpnn/SKILL.md", "dir": "skills/proteinmpnn", "环节": "实验与计算", "学科": "生命科学", "类型": "需GPU/远程", "cn": "用ProteinMPNN将蛋白质骨架反折叠为序列"}, {"id": "pydeseq2", "name": "pydeseq2", "description": "Differential gene expression analysis for bulk RNA-seq with PyDESeq2, including formulaic designs, Wald tests, FDR correction, LFC shrinkage, and result visualization.", "source": "claude-scientific-skills", "path": "skills/pydeseq2/SKILL.md", "dir": "skills/pydeseq2", "环节": "实验与计算", "学科": "生命科学", "类型": "即装即用", "cn": "用PyDESeq2进行RNA-seq差异表达基因分析"}, {"id": "pydicom", "name": "pydicom", "description": "Use pydicom to read, inspect, write, transform, and safely preflight local DICOM datasets and pixel data. Applies to DICOM metadata, transfer syntaxes, compression plugins, frames, private elements, JSON, and bounded de-identification review.", "source": "claude-scientific-skills", "path": "skills/pydicom/SKILL.md", "dir": "skills/pydicom", "环节": "实验与计算", "学科": "生命科学", "类型": "即装即用", "cn": "用pydicom读写和处理DICOM医学影像数据"}, {"id": "pyhealth", "name": "pyhealth", "description": "Build clinical/healthcare deep-learning pipelines with PyHealth — loading EHR/signal/imaging datasets (MIMIC-III/IV, eICU, OMOP, SleepEDF, ChestXray14, EHRShot), defining tasks (mortality, readmission, length-of-stay, drug recommendation, sleep staging, ICD coding, EEG events), instantiating models (Transformer, RETAIN, GAMENet, SafeDrug, MICRON, StageNet, AdaCare, CNN/RNN/MLP), training with the PyHealth Trainer, computing clinical metrics, and using medical code utilities (ICD/ATC/NDC/RxNorm l", "source": "claude-scientific-skills", "path": "skills/pyhealth/SKILL.md", "dir": "skills/pyhealth", "环节": "实验与计算", "学科": "生命科学", "类型": "即装即用", "cn": "用PyHealth构建临床深度学习预测模型"}, {"id": "pylabrobot", "name": "pylabrobot", "description": "Develop and review PyLabRobot lab-automation resources, liquid-handling plans, offline simulations, and supported-device integrations. Use for PyLabRobot protocols or API questions; keep physical execution behind an explicit operator safety gate.", "source": "claude-scientific-skills", "path": "skills/pylabrobot/SKILL.md", "dir": "skills/pylabrobot", "环节": "实验与计算", "学科": "生命科学", "类型": "即装即用", "cn": "开发PyLabRobot实验室自动化方案与离线模拟"}, {"id": "pyopenms", "name": "pyopenms", "description": "Complete mass spectrometry analysis platform. Use for proteomics and metabolomics workflows—feature detection, peptide/protein identification, label-free and isobaric quantification, adduct/accurate-mass annotation, and complex LC-MS/MS pipelines. Supports extensive file formats and algorithms. For simple spectral comparison and small-molecule library matching use matchms.", "source": "claude-scientific-skills", "path": "skills/pyopenms/SKILL.md", "dir": "skills/pyopenms", "环节": "实验与计算", "学科": "生命科学", "类型": "即装即用", "cn": "用pyopenms做质谱蛋白质组与代谢组分析"}, {"id": "pysam", "name": "pysam", "description": "Python/HTSlib workflows for genomic files. Use when reading, querying, filtering, or writing SAM/BAM/CRAM, VCF/BCF, FASTA/FASTQ, or tabix data with pysam, including pileup, coverage, indexing, and CRAM references.", "source": "claude-scientific-skills", "path": "skills/pysam/SKILL.md", "dir": "skills/pysam", "环节": "实验与计算", "学科": "生命科学", "类型": "即装即用", "cn": "用pysam读写处理SAM/BAM/VCF等基因组文件"}, {"id": "retrosynthesis_planning", "name": "retrosynthesis_planning", "description": "industrial retrosynthesis planning pipeline for target SMILES; run AiZynthFinder, normalize route JSON, query route molecules, rank routes, render figure-style route dashboards, and write analyst reports with retrosynthetic rationale.", "source": "OpenAI4S", "path": "skills/retrosynthesis_planning/SKILL.md", "dir": "skills/retrosynthesis_planning", "环节": "实验与计算", "学科": "生命科学", "类型": "即装即用", "cn": "用AiZynthFinder规划并评估目标分子逆合成路线"}, {"id": "scanpy", "name": "scanpy", "description": "Standard single-cell RNA-seq analysis pipeline. Use for QC, normalization, dimensionality reduction (PCA/UMAP/t-SNE), clustering, differential expression, visualization, and converting R-friendly single-cell formats such as Seurat or SingleCellExperiment RDS files into h5ad for Scanpy. Best for exploratory scRNA-seq analysis with established workflows. For deep learning models use scvi-tools; for data format questions use anndata.", "source": "claude-scientific-skills", "path": "skills/scanpy/SKILL.md", "dir": "skills/scanpy", "环节": "实验与计算", "学科": "生命科学", "类型": "即装即用", "cn": "用scanpy完成单细胞RNA-seq标准分析流程"}, {"id": "scgpt", "name": "scgpt", "description": "Embed and annotate single-cell expression data with scGPT, a foundation model for single-cell biology. Use this skill when: (1) Producing cell embeddings from an AnnData for clustering/integration, (2) Zero-shot or fine-tuned cell-type annotation, (3) Gene-level representation for perturbation/GRN tasks.", "source": "OpenAI4S", "path": "skills/scgpt/SKILL.md", "dir": "skills/scgpt", "环节": "实验与计算", "学科": "生命科学", "类型": "需GPU/远程", "cn": "用scGPT生成单细胞嵌入并注释细胞类型"}, {"id": "scvelo", "name": "scvelo", "description": "RNA velocity analysis with scVelo. Estimate cell state transitions from unspliced/spliced mRNA dynamics, infer trajectory directions, compute latent time, and identify driver genes in single-cell RNA-seq data. Complements Scanpy/scVI-tools for trajectory inference.", "source": "claude-scientific-skills", "path": "skills/scvelo/SKILL.md", "dir": "skills/scvelo", "环节": "实验与计算", "学科": "生命科学", "类型": "即装即用", "cn": "用scVelo从RNA速率推断细胞状态转变轨迹"}, {"id": "scvi-tools", "name": "scvi-tools", "description": "Probabilistic single-cell RNA-seq with scvi-tools — scVI for a batch-corrected latent space, scANVI for semi-supervised label transfer, and Bayesian differential expression. Reach for this skill to integrate scRNA-seq batches, embed cells for clustering, transfer annotations from a reference onto a query, or score differentially expressed genes per cluster. For spatial deconvolution / mapping use the cell2location, DestVI, or Tangram methods instead.", "source": "claude-scientific-skills+OpenAI4S", "path": "skills/scvi-tools/SKILL.md", "dir": "skills/scvi-tools", "环节": "实验与计算", "学科": "生命科学", "类型": "即装即用", "cn": "用scvi-tools做批次校正与单细胞概率建模"}, {"id": "solublempnn", "name": "solublempnn", "description": "Inverse-fold a backbone with SolubleMPNN — ProteinMPNN retrained on a soluble-PDB subset (Dauparas et al. 2022) — for sequences biased toward cytosolic expression and reduced aggregation. Reach for this skill when designs from vanilla ProteinMPNN are aggregating or going to inclusion bodies, when redesigning a membrane-adjacent fold for soluble expression, or when an E. coli expression screen is the next step.", "source": "OpenAI4S", "path": "skills/solublempnn/SKILL.md", "dir": "skills/solublempnn", "环节": "实验与计算", "学科": "生命科学", "类型": "需GPU/远程", "cn": "用SolubleMPNN设计可溶表达蛋白序列"}, {"id": "sympy", "name": "sympy", "description": "Use when you need exact symbolic math in Python — algebra, calculus, equation solving, symbolic linear algebra, or code generation via lambdify/LaTeX. Prefer NumPy or SciPy when floating-point approximations are sufficient.", "source": "claude-scientific-skills", "path": "skills/sympy/SKILL.md", "dir": "skills/sympy", "环节": "实验与计算", "学科": "生命科学", "类型": "即装即用", "cn": "用SymPy进行Python精确符号数学计算"}, {"id": "torchdrug", "name": "torchdrug", "description": "Build and troubleshoot TorchDrug 0.2.1 workflows for molecular graphs, property prediction, self-supervised pretraining, molecule generation, retrosynthesis, protein representation learning, and knowledge graph reasoning. Use when code imports torchdrug or needs its datasets, models, tasks, or Engine.", "source": "claude-scientific-skills", "path": "skills/torchdrug/SKILL.md", "dir": "skills/torchdrug", "环节": "实验与计算", "学科": "生命科学", "类型": "需GPU/远程", "cn": "构建TorchDrug分子图与药物发现工作流"}, {"id": "astropy", "name": "astropy", "description": "Core Python library for astronomy and astrophysics workflows that need Astropy APIs, including units/quantities, coordinates, FITS I/O, tables, time systems, WCS, and cosmology. Use when implementing or debugging astronomical data analysis code with Astropy.", "source": "claude-scientific-skills", "path": "skills/astropy/SKILL.md", "dir": "skills/astropy", "环节": "实验与计算", "学科": "物质科学", "类型": "即装即用", "cn": "用Astropy处理天文单位、坐标与FITS数据"}, {"id": "catalyst_sar_screening", "name": "catalyst_sar_screening", "description": "HARD-LOCKED Catalyst-Design-Agent FAIRChem UMA (uma-s-1p1, oc20) SAC SAR screening for dissolution potential / adsorption / overpotential. Always call run_pipeline with the user's metals/metrics into a fresh workdir and present ONLY that run's result[\"deliverables\"]. FORBIDDEN to return committed demo shells (metal_center_dissolution_*) as user results. FORBIDDEN tabular/heuristic/other MLIPs. If HF_TOKEN or hub unreachable, STOP and ask (HF_TOKEN / HF_ENDPOINT). Keywords: MLFF, UMA, OC20, catag", "source": "OpenAI4S", "path": "skills/catalyst_sar_screening/SKILL.md", "dir": "skills/catalyst_sar_screening", "环节": "实验与计算", "学科": "物质科学", "类型": "即装即用", "cn": "用FAIRChem UMA模型筛选催化剂的溶解电位、吸附和过电位"}, {"id": "datamol", "name": "datamol", "description": "Pythonic wrapper around RDKit with simplified interface and sensible defaults. Preferred for standard drug discovery including SMILES parsing, standardization, descriptors, fingerprints, clustering, 3D conformers, parallel processing. Returns native rdkit.Chem.Mol objects. For advanced control or custom parameters, use rdkit directly.", "source": "claude-scientific-skills", "path": "skills/datamol/SKILL.md", "dir": "skills/datamol", "环节": "实验与计算", "学科": "物质科学", "类型": "即装即用", "cn": "RDKit的简化Python封装，用于常规药物发现与分子处理"}, {"id": "deepchem", "name": "deepchem", "description": "Molecular ML with diverse featurizers and pre-built datasets. Use for property prediction (ADMET, toxicity) with traditional ML or GNNs when you want extensive featurization options and MoleculeNet benchmarks. Best for quick experiments with pre-trained models, diverse molecular representations. For graph-first PyTorch workflows use torchdrug; for benchmark datasets use pytdc.", "source": "claude-scientific-skills", "path": "skills/deepchem/SKILL.md", "dir": "skills/deepchem", "环节": "实验与计算", "学科": "物质科学", "类型": "即装即用", "cn": "分子机器学习库，用于ADMET/毒性预测与GNN建模"}, {"id": "molfeat", "name": "molfeat", "description": "Molecular featurization for ML (100+ featurizers). ECFP, MACCS, descriptors, pretrained models (ChemBERTa), convert SMILES to features, for QSAR and molecular ML.", "source": "claude-scientific-skills", "path": "skills/molfeat/SKILL.md", "dir": "skills/molfeat", "环节": "实验与计算", "学科": "物质科学", "类型": "即装即用", "cn": "提供100+分子特征化工具，将SMILES转为ML特征用于QSAR"}, {"id": "pymatgen", "name": "pymatgen", "description": "Analyze, validate, convert, and transform materials structures and computed materials data with current pymatgen APIs, including local phase diagrams, symmetry sensitivity, electronic-structure I/O, and explicitly bounded Materials Project queries.", "source": "claude-scientific-skills", "path": "skills/pymatgen/SKILL.md", "dir": "skills/pymatgen", "环节": "实验与计算", "学科": "物质科学", "类型": "即装即用", "cn": "分析、验证和转换材料结构及计算材料学数据"}, {"id": "qiskit", "name": "qiskit", "description": "Build, simulate, transpile, and execute quantum circuits with Qiskit and IBM Quantum Runtime. Use for Qiskit 2.x circuits and operators, V2 Sampler or Estimator primitives, target-aware transpilation, local or noisy simulation, IBM QPU execution, Runtime sessions or batches, error mitigation, and Qiskit ecosystem packages.", "source": "claude-scientific-skills", "path": "skills/qiskit/SKILL.md", "dir": "skills/qiskit", "环节": "实验与计算", "学科": "物质科学", "类型": "即装即用", "cn": "构建、模拟、转译和执行量子电路（基于IBM Quantum）"}, {"id": "qutip", "name": "qutip", "description": "Simulate and audit closed and open quantum-system models with QuTiP 5, including deterministic, trajectory, steady-state, spectral, and phase-space workflows. Use for local quantum-dynamics work where physical assumptions, dimensions, and numerical convergence must be explicit.", "source": "claude-scientific-skills", "path": "skills/qutip/SKILL.md", "dir": "skills/qutip", "环节": "实验与计算", "学科": "物质科学", "类型": "即装即用", "cn": "模拟和审计封闭与开放量子系统动力学（QuTiP 5）"}, {"id": "rdkit", "name": "rdkit", "description": "Cheminformatics toolkit for fine-grained molecular control. SMILES/SDF parsing, descriptors (MW, LogP, TPSA), fingerprints, substructure search, 2D/3D generation, similarity, reactions. For standard workflows with simpler interface, use datamol (wrapper around RDKit). Use rdkit for advanced control, custom sanitization, specialized algorithms.", "source": "claude-scientific-skills", "path": "skills/rdkit/SKILL.md", "dir": "skills/rdkit", "环节": "实验与计算", "学科": "物质科学", "类型": "即装即用", "cn": "化学信息学工具包，用于分子描述符、指纹和子结构搜索"}, {"id": "pennylane", "name": "pennylane", "description": "Hardware-agnostic quantum ML framework with automatic differentiation. Use when training quantum circuits via gradients, building hybrid quantum-classical models, or needing device portability across IBM/Google/Rigetti/IonQ. Best for variational algorithms (VQE, QAOA), quantum neural networks, and integration with PyTorch or JAX. For hardware-specific optimizations use qiskit (IBM) or cirq (Google); for open quantum systems use qutip.", "source": "claude-scientific-skills", "path": "skills/pennylane/SKILL.md", "dir": "skills/pennylane", "环节": "实验与计算", "学科": "数学量子", "类型": "即装即用", "cn": "硬件无关的量子机器学习框架，支持自动微分与混合模型"}, {"id": "pymoo", "name": "pymoo", "description": "Multi-objective optimization framework. NSGA-II, NSGA-III, MOEA/D, Pareto fronts, constraint handling, benchmarks (ZDT, DTLZ), for engineering design and optimization problems.", "source": "claude-scientific-skills", "path": "skills/pymoo/SKILL.md", "dir": "skills/pymoo", "环节": "实验与计算", "学科": "数学量子", "类型": "即装即用", "cn": "多目标优化框架，用于工程设计与Pareto前沿分析"}, {"id": "fluidsim", "name": "fluidsim", "description": "Plan, configure, inspect, restart, and analyze bounded FluidSim computational-fluid-dynamics simulations with explicit numerical-validity and HPC safety checks. Use for FluidSim solver selection, parameter review, FFT/MPI setup, output diagnostics, or restart compatibility.", "source": "claude-scientific-skills", "path": "skills/fluidsim/SKILL.md", "dir": "skills/fluidsim", "环节": "实验与计算", "学科": "工程技术", "类型": "即装即用", "cn": "规划、配置和分析FluidSim计算流体动力学模拟"}, {"id": "modal", "name": "modal", "description": "Modal is a serverless cloud platform for running Python on demand, including on-demand GPUs. Use when deploying or serving AI/ML models, running GPU-accelerated workloads (training, fine-tuning, inference), serving web endpoints, scheduling batch jobs, or scaling Python code to cloud containers with the Modal SDK.", "source": "claude-scientific-skills", "path": "skills/modal/SKILL.md", "dir": "skills/modal", "环节": "实验与计算", "学科": "工程技术", "类型": "需GPU/远程", "cn": "无服务器云平台，用于按需运行Python及GPU加速的AI/ML工作负载"}, {"id": "modal-run", "name": "modal-run", "description": "Use when the user asks to run heavy or GPU work on Modal (the cloud compute platform) — writing a Modal function in the workspace, running it with the user's own `modal` CLI + token, and bringing results back. Data-to-compute for jobs too big for the laptop, without a Slurm cluster.", "source": "open-science", "path": "runtime/skills/core/modal-run/SKILL.md", "dir": "runtime/skills/core/modal-run", "环节": "实验与计算", "学科": "工程技术", "类型": "需GPU/远程", "cn": "在Modal云平台运行GPU重计算任务并取回结果"}, {"id": "remote-compute", "name": "remote-compute", "description": "Use when the user asks to run, submit, monitor, or cancel a job on a remote machine over SSH — their own GPU/CPU server, a workstation, or a Slurm cluster (\"the cluster\", a login node, \"my 3090 box\", \"the compute server\"). Picks a saved machine, runs the work directly over SSH (or via Slurm when present), tracks it, and fetches results back into the workspace.", "source": "open-science", "path": "runtime/skills/core/remote-compute/SKILL.md", "dir": "runtime/skills/core/remote-compute", "环节": "实验与计算", "学科": "工程技术", "类型": "需GPU/远程", "cn": "通过SSH在远程服务器或Slurm集群提交管理计算作业"}, {"id": "remote-compute-nvidia", "name": "remote-compute-nvidia", "description": "Run GPU jobs on NVIDIA NIM microservices via host.compute.create('byoc:nvidia', ...). Covers both forms — self_hosted (an nvcr.io NIM container on a local GPU with --gpus all) and hosted (the fully-managed integrate.api.nvidia.com gateway, no local GPU) — sharing one submit→poll .result()→harvest flow. Load once you've decided to dispatch to NVIDIA NIM.", "source": "OpenAI4S", "path": "skills/remote-compute-nvidia/SKILL.md", "dir": "skills/remote-compute-nvidia", "环节": "实验与计算", "学科": "工程技术", "类型": "需GPU/远程", "cn": "通过NVIDIA NIM微服务运行GPU任务（自托管或托管）"}, {"id": "remote-compute-ssh", "name": "remote-compute-ssh", "description": "Submit→poll .result()→harvest workflow for the user's SSH/SLURM hosts. Load once you've decided to dispatch remote.", "source": "OpenAI4S", "path": "skills/remote-compute-ssh/SKILL.md", "dir": "skills/remote-compute-ssh", "环节": "实验与计算", "学科": "工程技术", "类型": "需GPU/远程", "cn": "远程SSH/SLURM主机的作业提交、轮询与结果回收流程"}, {"id": "database-lookup", "name": "database-lookup", "description": "Query documented public database APIs with explicit endpoints, filters, pagination, and provenance. Use when a scientific, regulatory, financial, or other database-backed fact must be retrieved reproducibly from a named source rather than inferred from general knowledge.", "source": "claude-scientific-skills", "path": "skills/database-lookup/SKILL.md", "dir": "skills/database-lookup", "环节": "实验与计算", "学科": "交叉通用", "类型": "数据连接器", "cn": "可复现地查询公开数据库API（含端点、筛选与溯源）"}, {"id": "evaluate-model", "name": "evaluate-model", "description": "Evaluate binary classification or regression models with confusion-matrix metrics, tie-aware ROC AUC, regression errors, and deterministic bootstrap confidence intervals; emphasizes held-out data, uncertainty, baselines, and subgroup checks.", "source": "OpenAI4S", "path": "skills/evaluate-model/SKILL.md", "dir": "skills/evaluate-model", "环节": "实验与计算", "学科": "交叉通用", "类型": "即装即用", "cn": "评估分类/回归模型：混淆矩阵、ROC AUC及Bootstrap置信区间"}, {"id": "pytdc", "name": "pytdc", "description": "Use Therapeutics Data Commons through the PyTDC Python package for registry discovery, approved dataset access, task-aware splits, evaluator metrics, benchmark groups, and bounded molecular-oracle workflows.", "source": "claude-scientific-skills", "path": "skills/pytdc/SKILL.md", "dir": "skills/pytdc", "环节": "实验与计算", "学科": "交叉通用", "类型": "即装即用", "cn": "通过PyTDC访问治疗数据共享库（数据集、任务划分与评估）"}, {"id": "timesfm-forecasting", "name": "timesfm-forecasting", "description": "Zero-shot time series forecasting with Google's TimesFM foundation model. Use for any univariate time series (sales, sensors, energy, vitals, weather) without training a custom model. Supports CSV/DataFrame/array inputs with point forecasts and prediction intervals. Includes a preflight system checker script to verify RAM/GPU before first use.", "source": "claude-scientific-skills", "path": "skills/timesfm-forecasting/SKILL.md", "dir": "skills/timesfm-forecasting", "环节": "实验与计算", "学科": "交叉通用", "类型": "需GPU/远程", "cn": "用Google TimesFM基础模型进行零样本时间序列预测"}, {"id": "exploratory-data-analysis", "name": "exploratory-data-analysis", "description": "Perform bounded, local exploratory analysis of explicitly supported scientific files. Use for redacted CSV/TSV/JSON profiles; optional NumPy, HDF5, FASTA/FASTQ, and basic image metadata inspection; missingness/leakage audits; outlier and transformation sensitivity; and rigorous EDA report scaffolds. Other domain formats are reference-only and unknown formats fail closed.", "source": "claude-scientific-skills", "path": "skills/exploratory-data-analysis/SKILL.md", "dir": "skills/exploratory-data-analysis", "环节": "数据分析", "学科": "生命科学", "类型": "即装即用", "cn": "对科学数据文件进行本地探索性分析（CSV/HDF5/FASTA等）"}, {"id": "large-file", "name": "large-file", "description": "Use BEFORE reading any data file that could be large (CSV/TSV, Parquet, HDF5, FITS, NetCDF, NDJSON, genomics FASTQ/FASTA/VCF/BAM, GRIB, ROOT, or big text/simulation logs like VASP OUTCAR). Returns a compact memory pointer — header/schema/shape/sample/key numbers — by introspection and sampling in bounded memory, so you never load a file bigger than the context window into the model. Reference data via the pointer; read specific ranges deterministically.", "source": "open-science", "path": "runtime/skills/core/large-file/SKILL.md", "dir": "runtime/skills/core/large-file", "环节": "数据分析", "学科": "生命科学", "类型": "即装即用", "cn": "读取大文件前预检（CSV/HDF5/基因组数据/模拟日志等）"}, {"id": "geopandas", "name": "geopandas", "description": "Guidance and local audit tools for Python workflows that directly use GeoPandas GeoSeries, GeoDataFrame, spatial operations, or vector-data I/O.", "source": "claude-scientific-skills", "path": "skills/geopandas/SKILL.md", "dir": "skills/geopandas", "环节": "数据分析", "学科": "地球环境", "类型": "即装即用", "cn": "GeoPandas地理空间数据处理与本地审计工具"}, {"id": "polars", "name": "polars", "description": "High-performance DataFrame library for Python ETL, analytics, and pandas migration. Use for expression-based data manipulation with lazy query optimization, parallel execution, streaming out-of-core processing, Arrow interoperability, and optional GPU execution.", "source": "claude-scientific-skills", "path": "skills/polars/SKILL.md", "dir": "skills/polars", "环节": "数据分析", "学科": "数学量子", "类型": "需GPU/远程", "cn": "Polars高性能DataFrame库：惰性查询优化与并行ETL分析"}, {"id": "dask", "name": "dask", "description": "Distributed computing for larger-than-RAM pandas/NumPy workflows. Use when you need to scale existing pandas/NumPy code beyond memory or across clusters. Best for parallel file processing, distributed ML, integration with existing pandas code. For out-of-core analytics on single machine use vaex; for in-memory speed use polars.", "source": "claude-scientific-skills", "path": "skills/dask/SKILL.md", "dir": "skills/dask", "环节": "数据分析", "学科": "交叉通用", "类型": "即装即用", "cn": "用Dask实现超内存pandas/NumPy分布式计算"}, {"id": "matplotlib", "name": "matplotlib", "description": "Low-level plotting library for full customization. Use when you need fine-grained control over every plot element, creating novel plot types, or integrating with specific scientific workflows. Export to PNG/PDF/SVG for publication. For quick statistical plots use seaborn; for interactive plots use plotly; for publication-ready multi-panel figures with journal styling, use scientific-visualization.", "source": "claude-scientific-skills", "path": "skills/matplotlib/SKILL.md", "dir": "skills/matplotlib", "环节": "数据分析", "学科": "交叉通用", "类型": "即装即用", "cn": "用matplotlib精细定制科研图表细节"}, {"id": "pymc", "name": "pymc", "description": "Bayesian modeling with PyMC. Build hierarchical models, MCMC (NUTS), variational inference, LOO/WAIC comparison, posterior checks, for probabilistic programming and inference.", "source": "claude-scientific-skills", "path": "skills/pymc/SKILL.md", "dir": "skills/pymc", "环节": "数据分析", "学科": "交叉通用", "类型": "即装即用", "cn": "用PyMC构建贝叶斯模型与概率推断"}, {"id": "scikit-learn", "name": "scikit-learn", "description": "Machine learning in Python with scikit-learn. Use when working with supervised learning (classification, regression), unsupervised learning (clustering, dimensionality reduction), model evaluation, hyperparameter tuning, preprocessing, or building ML pipelines. Provides comprehensive reference documentation for algorithms, preprocessing techniques, pipelines, and best practices.", "source": "claude-scientific-skills", "path": "skills/scikit-learn/SKILL.md", "dir": "skills/scikit-learn", "环节": "数据分析", "学科": "交叉通用", "类型": "即装即用", "cn": "用scikit-learn实现机器学习建模评估"}, {"id": "scikit-survival", "name": "scikit-survival", "description": "Build, evaluate, and audit right-censored or competing-risk survival workflows with scikit-survival, including leakage-safe preprocessing, model selection, probability prediction, and censoring-aware metrics.", "source": "claude-scientific-skills", "path": "skills/scikit-survival/SKILL.md", "dir": "skills/scikit-survival", "环节": "数据分析", "学科": "交叉通用", "类型": "即装即用", "cn": "用scikit-survival构建生存分析模型"}, {"id": "seaborn", "name": "seaborn", "description": "Statistical visualization with pandas integration. Use for quick exploration of distributions, relationships, and categorical comparisons with attractive defaults. Best for box plots, violin plots, pair plots, heatmaps. Built on matplotlib. For interactive plots use plotly; for publication styling use scientific-visualization.", "source": "claude-scientific-skills", "path": "skills/seaborn/SKILL.md", "dir": "skills/seaborn", "环节": "数据分析", "学科": "交叉通用", "类型": "即装即用", "cn": "用seaborn快速绘制统计分布图"}, {"id": "shap", "name": "shap", "description": "Explain and audit machine-learning predictions with SHAP. Use for selecting SHAP explainers and maskers, computing and validating feature attributions, handling multi-output explanations, and producing local or global SHAP visualizations.", "source": "claude-scientific-skills", "path": "skills/shap/SKILL.md", "dir": "skills/shap", "环节": "数据分析", "学科": "交叉通用", "类型": "即装即用", "cn": "用SHAP解释审计机器学习预测"}, {"id": "statistical-power", "name": "statistical-power", "description": "Sample-size and statistical power calculations for planning studies. Use whenever someone asks \"how many subjects/samples/replicates do I need\", wants an a priori power analysis, a minimum detectable effect (MDE), a power curve, or needs to justify a sample size for a grant, IRB protocol, or pre-registration. Covers closed-form power for t-tests, ANOVA, proportions, correlations, chi-square, and regression, plus simulation-based (Monte Carlo) power for designs with no formula — logistic/Poisson ", "source": "claude-scientific-skills", "path": "skills/statistical-power/SKILL.md", "dir": "skills/statistical-power", "环节": "数据分析", "学科": "交叉通用", "类型": "即装即用", "cn": "计算研究所需样本量与统计功效"}, {"id": "statsmodels", "name": "statsmodels", "description": "Statistical models library for Python. Use when you need specific model classes (OLS, GLM, mixed models, ARIMA) with detailed diagnostics, residuals, and inference. Best for econometrics, time series, rigorous inference with coefficient tables. For guided statistical test selection with APA reporting use statistical-analysis.", "source": "claude-scientific-skills", "path": "skills/statsmodels/SKILL.md", "dir": "skills/statsmodels", "环节": "数据分析", "学科": "交叉通用", "类型": "即装即用", "cn": "用statsmodels构建统计模型与诊断"}, {"id": "umap-learn", "name": "umap-learn", "description": "Use UMAP-learn for nonlinear dimensionality reduction, 2D/3D embeddings, clustering preprocessing, supervised or semi-supervised UMAP, DensMAP, AlignedUMAP, and Parametric UMAP workflows.", "source": "claude-scientific-skills", "path": "skills/umap-learn/SKILL.md", "dir": "skills/umap-learn", "环节": "数据分析", "学科": "交叉通用", "类型": "即装即用", "cn": "用UMAP-learn进行非线性降维嵌入"}, {"id": "publication-figures", "name": "publication-figures", "description": "Use whenever you generate a chart, plot, or figure with matplotlib (or seaborn) in this workspace. Applies the Open Science publication figure style so every generated figure is publication-grade and shares one palette with the app's native charts. Not for interactive plotly/HTML — those follow the same palette manually.", "source": "open-science", "path": "runtime/skills/core/publication-figures/SKILL.md", "dir": "runtime/skills/core/publication-figures", "环节": "论文写作", "学科": "生命科学", "类型": "即装即用", "cn": "用matplotlib生成出版级科研图表"}, {"id": "scientific-schematics", "name": "scientific-schematics", "description": "Create publication-quality scientific diagrams using Nano Banana 2 AI with smart iterative refinement. Uses Gemini 3.6 Flash for quality review. Only regenerates if quality is below threshold for your document type. Specialized in neural network architectures, system diagrams, flowcharts, biological pathways, and complex scientific visualizations.", "source": "claude-scientific-skills", "path": "skills/scientific-schematics/SKILL.md", "dir": "skills/scientific-schematics", "环节": "论文写作", "学科": "生命科学", "类型": "即装即用", "cn": "用Nano Banana 2 AI生成科研示意图"}, {"id": "venue-templates", "name": "venue-templates", "description": "Prepare journal manuscripts, conference papers, research posters, and grant documents using venue-specific formatting guidance and bundled LaTeX scaffolds. Use when selecting an official template, checking current page or anonymity rules, adapting academic writing to a venue, or inspecting a submission PDF.", "source": "claude-scientific-skills", "path": "skills/venue-templates/SKILL.md", "dir": "skills/venue-templates", "环节": "论文写作", "学科": "生命科学", "类型": "即装即用", "cn": "用LaTeX模板快速制作符合期刊会议要求的各类文稿。"}, {"id": "figure-composer", "name": "figure-composer", "description": "Compose one publication-grade multi-panel figure. Entry from a one-line claim + data refs, OR from an existing figure via `derive_outline(png)`. Runs a per-figure loop: outline (12-col grid, per-panel ask + label_budget) → fan-out one sub-agent per panel (each loads `figure-style`) → tile + stamp letters → adversarial composite review with two-tier feedback (Tier-1 outline_revisions / Tier-2 per-panel violations) → regen affected panels, ≤3 rounds. Loads panel_task / compose_figure / compose_cro", "source": "OpenAI4S", "path": "skills/figure-composer/SKILL.md", "dir": "skills/figure-composer", "环节": "论文写作", "学科": "交叉通用", "类型": "即装即用", "cn": "从数据和论点生成出版级多面板科研图表。"}, {"id": "figure-style", "name": "figure-style", "description": "Publication-grade figure correctness and legibility rules. Load before drawing any plot and call `apply_figure_style()` — sets a role-mapped font-size ladder, outward ticks, frameless legends, and 300-dpi output. The skill is a checklist, not a house look: data fidelity (claim-titles tested against every row, excluded data never enters summaries), label economy (floor and ceiling), colour threading, chart-choice-by-data-shape, layout, and a render-then-verify QA loop (bbox collision + per-panel ", "source": "OpenAI4S", "path": "skills/figure-style/SKILL.md", "dir": "skills/figure-style", "环节": "论文写作", "学科": "交叉通用", "类型": "即装即用", "cn": "提供出版级图表规范，自动设置字体刻度等样式。"}, {"id": "latex-posters", "name": "latex-posters", "description": "Create professional research posters in LaTeX using beamerposter, tikzposter, or baposter. Support for conference presentations, academic posters, and scientific communication. Includes layout design, color schemes, multi-column formats, figure integration, and poster-specific best practices for visual communication.", "source": "claude-scientific-skills", "path": "skills/latex-posters/SKILL.md", "dir": "skills/latex-posters", "环节": "论文写作", "学科": "交叉通用", "类型": "即装即用", "cn": "用LaTeX制作专业学术海报，支持多种版式。"}, {"id": "markdown-mermaid-writing", "name": "markdown-mermaid-writing", "description": "Comprehensive markdown and Mermaid diagram writing skill. Use when creating any scientific document, report, analysis, or visualization. Establishes text-based diagrams as the default documentation standard with full style guides (markdown + mermaid), 24 diagram type references, and 9 document templates.", "source": "claude-scientific-skills", "path": "skills/markdown-mermaid-writing/SKILL.md", "dir": "skills/markdown-mermaid-writing", "环节": "论文写作", "学科": "交叉通用", "类型": "即装即用", "cn": "用Markdown和Mermaid编写含文本图表的科学文档。"}, {"id": "peer-review", "name": "peer-review", "description": "Prepare evidence-bounded, constructive peer-review drafts and structured manuscript assessments. Use for authorized review of scientific manuscripts, protocols, preprints, or research proposals; reporting-guideline selection; claim–evidence checks; methods, statistics, reproducibility, ethics, figure/table, and citation critique; or revision-response planning.", "source": "claude-scientific-skills", "path": "skills/peer-review/SKILL.md", "dir": "skills/peer-review", "环节": "论文写作", "学科": "交叉通用", "类型": "即装即用", "cn": "撰写有依据的建设性同行评审意见和稿件评估。"}, {"id": "scientific-slides", "name": "scientific-slides", "description": "Build slide decks and presentations for research talks. Use this for making PowerPoint slides, conference presentations, seminar talks, research presentations, thesis defense slides, or any scientific talk. Provides slide structure, design templates, timing guidance, and visual validation. Works with PowerPoint and LaTeX Beamer.", "source": "claude-scientific-skills", "path": "skills/scientific-slides/SKILL.md", "dir": "skills/scientific-slides", "环节": "论文写作", "学科": "交叉通用", "类型": "即装即用", "cn": "制作学术报告、会议演讲和答辩用的幻灯片。"}, {"id": "scientific-writing", "name": "scientific-writing", "description": "Draft, revise, and audit scientific manuscripts or reports with explicit evidence provenance, reporting-guideline coverage, authorship accountability, confidentiality controls, and local consistency checks. Use for manuscript sections, references, declarations, tables, figures, or submission preparation when scientific accuracy and traceability matter.", "source": "claude-scientific-skills", "path": "skills/scientific-writing/SKILL.md", "dir": "skills/scientific-writing", "环节": "论文写作", "学科": "交叉通用", "类型": "即装即用", "cn": "起草修改科学文稿，确保证据可溯、规范合规。"}, {"id": "domain-check", "name": "domain-check", "description": "Use whenever you write or run scientific analysis code (physics, earth/geo, biology, chemistry, or social science) in this workspace — before executing it and again after generating results. Runs a deterministic domain-correctness gate that catches code which runs but is scientifically wrong (unit/dimension mismatch, Euclidean distance on lat/lon without a CRS, 0-based/1-based coordinate and strand errors, impossible SMILES valence, uncorrected multiple comparisons, averaging a categorical code)", "source": "open-science", "path": "runtime/skills/core/domain-check/SKILL.md", "dir": "runtime/skills/core/domain-check", "环节": "诚信治理", "学科": "生命科学", "类型": "即装即用", "cn": "运行科学分析代码前后自动检查领域特定错误。"}, {"id": "traceability-review", "name": "traceability-review", "description": "Use when the user asks to review, verify, or audit a report, manuscript, or analysis in the workspace for traceability — resolving citations, flagging numbers with no source, and checking figures against the code that generated them. Emits a structured review block the app renders as reviewer findings. Verifies traceability, never \"correctness\".", "source": "open-science", "path": "runtime/skills/core/traceability-review/SKILL.md", "dir": "runtime/skills/core/traceability-review", "环节": "诚信治理", "学科": "生命科学", "类型": "即装即用", "cn": "审查报告稿件，核对引文来源和数据可追溯性。"}, {"id": "audit-dataset", "name": "audit-dataset", "description": "Audit tabular datasets before analysis or training for schema drift, missing values, duplicate rows or IDs, target imbalance, and entity or group leakage across splits using pure-stdlib helpers.", "source": "OpenAI4S", "path": "skills/audit-dataset/SKILL.md", "dir": "skills/audit-dataset", "环节": "诚信治理", "学科": "交叉通用", "类型": "即装即用", "cn": "分析前审计表格数据，检查缺失值、泄漏等问题。"}, {"id": "stats-integrity", "name": "stats-integrity", "description": "Use whenever you run statistical analysis for the social sciences (regression, hypothesis tests, econometrics) or read Stata (.dta) / SPSS (.sav) data in this workspace. Enforces an execute-don't-interpret boundary (surface estimates, don't volunteer causal claims), checks the analysis against a preregistration plan for HARKing, verifies reproducible seeds, and reproduces .dta/.sav estimates via R. Flags integrity risks; never certifies the analysis is sound.", "source": "open-science", "path": "runtime/skills/core/stats-integrity/SKILL.md", "dir": "runtime/skills/core/stats-integrity", "环节": "诚信治理", "学科": "交叉通用", "类型": "即装即用", "cn": "确保社科统计分析可复现，支持Stata和SPSS数据。"}]};